   archivedSurfaceContract:(viewport,owner)=>{assert.equal(on,false,'archived preflight belongs only to immutable baseline');const b=city.buildings.find(b=>b.id===owner),pin=D079_ARCHIVED_SURFACES[sample+':'+b.k+':'+b.v]?.[viewport.W];assert.ok(pin,'exact archived full owner contract pin');const contract=d079OwnerSurfaceContract({scene,meshes:modelMeshes,owners:modelOwners,n:city.n},pin.view,viewport,owner);assert.equal(contract.sha256,pin.sha256,'entire final-cohort historical-camera contract remains byte exact');assert.equal(contract.sourceGeometrySha256,pin.sourceGeometrySha256,'every final-cohort baseline mesh remains exact');assert.equal(contract.requiredSamples.length,pin.requiredSamples);assert.equal(contract.originalHits,pin.originalHits);assert.equal(contract.originalBlockedHits,pin.originalBlockedHits);const {sha256,...body}=contract,initial={...body,sourceGeometrySha256:pin.initialSourceGeometrySha256};assert.equal(createHash('sha256').update(JSON.stringify(initial)).digest('hex'),pin.initialSha256,'all original pre-code contract fields and probes remain byte exact, only the separately proved final-cohort source hash differs');return frozen({...initial,sha256:pin.initialSha256});},
   productionSurfaceContract:(viewport,owner)=>{assert.equal(on,false,'production preflight belongs only to immutable baseline');const b=city.buildings.find(b=>b.id===owner),pin=D079_ARCHIVED_SURFACES[sample+':'+b.k+':'+b.v]?.[viewport.W];assert.ok(pin);const contract=d079OwnerSurfaceContract({scene,meshes:modelMeshes,owners:modelOwners,n:city.n},pin.productionView,viewport,owner);assert.equal(contract.sha256,pin.productionSha256,'exact production-camera pre-code contract remains byte exact');return contract;},
   surfaceVisibility:(view,viewport,contract)=>d079OwnerSurfaceRayAudit({scene,meshes:modelMeshes,owners:modelOwners,n:city.n},view,viewport,contract),
